namespace {
void require(bool b,const char* why){if(!b)throw std::runtime_error(why);}
uint8_t byte(const ProfileJson& v,unsigned high=255){require(v.is_number_integer()&&!v.is_boolean(),"I2C byte must be an integer");if(v.is_number_unsigned()){const auto n=v.get<uint64_t>();require(n<=high,"I2C byte out of range");return static_cast<uint8_t>(n);}const auto n=v.get<int64_t>();require(n>=0&&static_cast<uint64_t>(n)<=high,"I2C byte out of range");return static_cast<uint8_t>(n);}
std::string text(const ProfileJson& v){require(v.is_string(),"I2C identity must be a string");const auto s=v.get<std::string>();require(!s.empty()&&s.size()<=4096&&s.find('\0')==std::string::npos,"Invalid I2C identity");return s;}
void keys(const ProfileJson& j,const std::set<std::string>& expected){require(j.is_object()&&j.size()==expected.size(),"Invalid I2C profile fields");for(const auto& k:expected)require(j.contains(k),"Missing I2C profile field");}
}
PythonNct3933Profile parse_python_nct3933_profile(const ProfileJson& j){
 require(j.is_object()&&j.value("format",ProfileJson())=="i2c.current_dac_control","This I2C saved-control format has no qualified native profile adapter yet");
 keys(j,{"profile","sha256","port","addr7","rail","format","current_dac_control","display_name"});
 PythonNct3933Profile result;result.profile=text(j["profile"]);result.rail=text(j["rail"]);result.recipe_sha256=text(j["sha256"]);
 require(text(j["format"])=="i2c.current_dac_control","Unsupported I2C controller profile format");
 require(result.profile=="NCT3933U - three current offsets"&&result.rail=="OUT1/OUT2/OUT3","Unsupported NCT released recipe identity");(void)text(j["display_name"]);
 result.route.port=byte(j["port"],7);result.route.addr7=byte(j["addr7"],0x15);require(result.route.addr7>=0x10,"Unsupported NCT address");
 const auto recipe=std::string("{\"addr7\": ")+std::to_string(result.route.addr7)+", \"contract\": 1, \"controller\": \"NCT3933U\", \"port\": "+std::to_string(result.route.port)+", \"units\": \"nominal_microamps\"}";
 require(result.recipe_sha256==druta::sha256_hex(reinterpret_cast<const uint8_t*>(recipe.data()),recipe.size()),"NCT released recipe hash mismatch");
 const auto& control=j["current_dac_control"];keys(control,{"outputs","configuration"});require(control["outputs"].is_array()&&control["outputs"].size()==3,"NCT requires three outputs");
 for(size_t i=0;i<3;++i)result.outputs[i]=byte(control["outputs"][i]);result.configuration=byte(control["configuration"]);return result;
}
namespace {
const char* released_mp2888 = R"DRUTA({"bus": {"addr7": 32, "port": 1}, "identity": [{"bytes": 1, "equals": 160, "note": "MFR_PMBUS_ADDR. bit7=1, 3 MSB=010, 4 LSB=0000 -> 0x20. The part states its own address, so this identifies it and confirms the strap in one read.", "reg": 190}], "limits": {"envelope_max_mv": 100.0, "envelope_min_mv": -200.0, "plausible_rail_mv": [400.0, 1300.0], "rail_ceiling_mv": 1200.0, "sanity_max_rail_mv": 2000.0}, "match": {"pci_device": ["0x1E02"], "pci_subsys": ["0x12A310DE"]}, "never_write": [{"reg": 4, "why": "MFR_USER_PWD. One-shot password: locks out PMBus writes until a power cycle, and can be committed to EEPROM. There is no undo."}], "profile": {"author": "Thermetery", "format": 1, "name": "RTX 2080 Ti - NVVDD (MP2888A)", "rail": "NVVDD", "regulator": "MPS MP2888A"}, "provenance": {"address": "measured: 0xBE reads 0xA0. Independently agrees with datasheet Table 6 p.30 (20h for ADDR = 0 V), which matches the address strap as fitted on the authoring card", "behaviour": "measured under gpuload bandwidth load at NVVDD 1050 mV, 2026-09-04", "datasheet": "MP2888A Rev. 1.1, 12/25/2018 (public MPS datasheet)", "hardware": "the two SMBus links to the core VRM fitted by hand on the authoring card; regulator identity then confirmed on the bus", "registers": "command table pp.34-37; VOUT_OFFSET/VOUT_MAX bit fields p.43; VID offset range p.17"}, "telemetry": [{"bytes": 2, "encoding": "uint", "key": "vout_mv", "note": "READ_VOUT is DIRECT millivolts on this part, not LINEAR11 - it read 681 at the same instant NVAPI reported 681.25 mV. IOUT and TEMP below use different encodings, so do not assume one format across commands.", "reg": 139, "scale": 1.0}, {"bytes": 2, "encoding": "linear11", "key": "iout_a", "reg": 140}, {"bytes": 2, "encoding": "uint", "key": "vrm_temp_c", "reg": 141, "scale": 0.1}, {"bits": "8:0", "bytes": 2, "encoding": "uint", "key": "vout_max_mv", "note": "VOUT_MAX. Reads 1300 mV here. The regulator clamps anything above it, and OVP1 sits at VOUT_MAX + 400 mV. This is the hardware ceiling; rail_ceiling_mv below is Druta's, and is deliberately lower.", "reg": 36, "scale": 6.25}], "verify": {"expect_deadband_mv": 31.0, "min_loaded_vout_mv": 800.0, "rungs_mv": [6.25, 12.5, 25.0, 50.0, 75.0]}, "write": [{"bits": "7:0", "bytes": 2, "encoding": "int", "key": "offset_mv", "lsb_mv": 6.25, "note": "VOUT_OFFSET. bytes=2 and bits=7:0 are different numbers and both matter: writing this as a 16-bit value makes every NEGATIVE offset fail read-back, because the reserved half is dropped.", "raw_max": 112, "raw_min": -111, "reg": 35}]})DRUTA";
const char* released_mp29816 = R"DRUTA({"bus": {"addr7": 48, "port": 2}, "identity": [{"bytes": 5, "equals": 44570116, "note": "Measured bytes 04 16 A8 02 00 match the four-byte payload 0x0002A816 in EVC2's MP29816 Detect entry, annotated MPS29816A. This is a source-backed device ID, in addition to the board fingerprints below.", "reg": 173}, {"bytes": 4, "equals": 1297109763, "fingerprint": true, "note": "Observed MFR_ID bytes 03 53 50 4D: count 3 and manufacturer code MPS.", "reg": 153}, {"bytes": 7, "equals": 21728798838961670, "fingerprint": true, "note": "Observed MFR_MODEL bytes 06 36 31 38 3A 32 4D. Exact fingerprint, not a claimed documented model-ID decoding.", "reg": 154}, {"bytes": 3, "equals": 258, "fingerprint": true, "note": "Observed MFR_REVISION bytes 02 01 00. Other revisions are untested.", "reg": 155}, {"bytes": 1, "equals": 0, "fingerprint": true, "note": "Only already-selected PAGE 0 is supported. Never select a page by writing.", "reg": 0}, {"bytes": 2, "fingerprint": true, "mask": 7168, "note": "VOUT_SCALE_LOOP selector bits 12:10 must remain 1 (5 mV/LSB). Other fields are not scaling bits.", "reg": 41, "value": 1024}], "limits": {"envelope_max_mv": 50.0, "envelope_min_mv": -50.0, "plausible_rail_mv": [400.0, 1300.0], "rail_ceiling_mv": 1200.0, "sanity_max_rail_mv": 2000.0}, "match": {"pci_device": ["0x2C02"], "pci_subsys": ["0x89DE1043"]}, "profile": {"author": "Thermetery", "format": 1, "name": "ASUS RTX 5080 Astral - MP29816 (write path unverified)", "rail": "NVVDD", "regulator": "MPS MP29816", "runtime_checks": true}, "provenance": {"address": "Measured on PCI 2C02/subsystem 89DE1043, VBIOS 98.03.3b.c0.6f, driver 580.97: NVAPI port 2, 7-bit address 0x30.", "behaviour": "Bench survey 2026-09-08: 40 stable loaded samples read 1040 mV versus NVAPI core voltage 1035-1040 mV (mean absolute difference 0.625 mV), supporting PAGE 0 as NVVDD. Manufacturer/model/revision, PAGE and scale were stable across all 70 follow-up samples. Read command 0xAD additionally matched EVC2's MP29816 device ID. Writes have not been verified: NVAPI rejected them and direct RM reported NV_ERR_INVALID_STATE.", "datasheet": "Public Linux drivers/hwmon/pmbus/mp2869.c, GPL-2.0-or-later; explicitly supports mp29816: https://github.com/torvalds/linux/blob/master/drivers/hwmon/pmbus/mp2869.c", "hardware": "ASUS RTX 5080 Astral; I2C already reachable. The owner's 12 V shunt modification is separate from this controller telemetry path.", "offset": "ElmorLabs EVC2 1.0.1.18_t6, exact MP29816.xml: Loop 1 VID Offset, command 0x22, two-byte transaction, bits 7:0 signed two's complement at 5 mV/LSB, gated by PAGE 0 and 0x29 bits 12:10 = 1. Public-source evidence: experiments/power-5080-20260908/evc2-public-source/MP29816.xml. Register facts transcribed; this file does not assert successful hardware writes.", "registers": "Linux mp2869.c: READ_VOUT lower 12 bits; VOUT_SCALE_LOOP (0x29) bits 12:10 equal 1 select 5 mV/LSB. Only that observed configuration is supported."}, "telemetry": [{"bits": "11:0", "bytes": 2, "encoding": "uint", "key": "vout_mv", "note": "Read-only NVVDD voltage on already-selected PAGE 0, supported by stable loaded correlation with NVAPI core voltage. Current and temperature conversions are not yet bench-validated and are omitted.", "reg": 139, "scale": 5.0}], "verify": {"min_loaded_vout_mv": 800.0, "rungs_mv": [5.0, 10.0, 15.0, 20.0]}, "write": [{"bits": "7:0", "bytes": 2, "encoding": "int", "key": "offset_mv", "lsb_mv": 5.0, "note": "EVC2 MP29816 Loop 1 VID Offset map. Preserve the upper byte through read-modify-write. Signed-byte endpoints describe encoding only; physical response and usable operating range remain unverified on this board. No PAGE, mode, load-line or protection writes are allowed.", "raw_max": 127, "raw_min": -128, "reg": 34}]})DRUTA";
struct CompoundIdentity {I2cRoute route{};std::string profile,rail,hash;};
CompoundIdentity compound(const ProfileJson& j,bool up){
 if(up)keys(j,{"profile","sha256","port","addr7","rail","format","control","display_name"});else keys(j,{"profile","sha256","port","addr7","rail","control","display_name"});
 CompoundIdentity c;c.route.port=byte(j["port"],7);c.route.addr7=byte(j["addr7"],0x77);require(c.route.addr7>=8,"Unsupported controller address");
 char label[120];std::snprintf(label,sizeof(label),up?"uP9512R offsets (port %u, 0x%02X; physical rail unassigned)":"NCP4206 output (port %u, 0x%02X; physical rail unassigned)",unsigned(c.route.port),unsigned(c.route.addr7));
 c.profile=text(j["profile"]);c.rail=text(j["rail"]);c.hash=text(j["sha256"]);(void)text(j["display_name"]);require(c.profile==label&&c.rail=="Controller output","Unsupported released controller recipe identity");
 if(up)require(text(j["format"])=="i2c.multi_state_offset","Unsupported uP controller format");
 const auto port=std::to_string(c.route.port),addr=std::to_string(c.route.addr7);
 const auto recipe=up?"{\"addr7\": "+addr+", \"identity\": [0, 43], \"kind\": \"up9512r-offset-v1\", \"port\": "+port+"}":"{\"addr7\": "+addr+", \"identity\": null, \"kind\": \"ncp4206-absolute-v1\", \"min_mv\": 600, \"normal_max\": 1281, \"port\": "+port+", \"vid_max\": 1600, \"xoc_max\": 2000}";
 require(c.hash==druta::sha256_hex(reinterpret_cast<const uint8_t*>(recipe.data()),recipe.size()),"Released controller recipe hash mismatch");return c;
}
}
PythonUp9512rProfile parse_python_up9512r_profile(const ProfileJson& j){const auto c=compound(j,true);const auto& state=j["control"];keys(state,{"kind","offsets_mv","enabled"});require(text(state["kind"])=="up9512r-offset-v1"&&state["enabled"].is_boolean()&&state["offsets_mv"].is_array()&&state["offsets_mv"].size()==5,"Invalid uP9512R compound state");PythonUp9512rProfile out;out.route=c.route;out.profile=c.profile;out.rail=c.rail;out.recipe_sha256=c.hash;out.enabled=state["enabled"].get<bool>();for(size_t i=0;i<5;++i){out.offsets_mv[i]=byte(state["offsets_mv"][i],150);require(out.offsets_mv[i]%10==0,"uP9512R offset must be in 10 mV steps");}return out;}
PythonNcp4206Profile parse_python_ncp4206_profile(const ProfileJson& j){const auto c=compound(j,false);const auto& state=j["control"];keys(state,{"kind","enabled","command"});require(text(state["kind"])=="absolute_vid"&&state["enabled"].is_boolean(),"Invalid NCP4206 absolute state");PythonNcp4206Profile out;out.route=c.route;out.profile=c.profile;out.rail=c.rail;out.recipe_sha256=c.hash;out.enabled=state["enabled"].get<bool>();out.command=byte(state["command"]);require(!out.enabled||(out.command>=2&&out.command<=198),"Active NCP4206 command is not a VID");return out;
}
namespace {
std::string python_json(const ProfileJson& value){const auto compact=value.dump(-1,' ',true);std::string out;bool quoted=false,escape=false;for(char c:compact){out.push_back(c);if(quoted){if(escape)escape=false;else if(c=='\\')escape=true;else if(c=='"')quoted=false;}else if(c=='"')quoted=true;else if(c==','||c==':')out.push_back(' ');}return out;}
std::string digest(const ProfileJson& value){const auto raw=python_json(value);return druta::sha256_hex(reinterpret_cast<const uint8_t*>(raw.data()),raw.size());}
}
PythonOffsetProfile parse_python_offset_profile(const ProfileJson& j){
 keys(j,{"profile","sha256","port","addr7","rail","offset_mv","display_name"});PythonOffsetProfile out;out.profile=text(j["profile"]);out.rail=text(j["rail"]);out.recipe_sha256=text(j["sha256"]);(void)text(j["display_name"]);out.route.port=byte(j["port"],7);out.route.addr7=byte(j["addr7"],0x77);require(out.route.addr7>=8,"Invalid controller route");require(j["offset_mv"].is_number()&&!j["offset_mv"].is_boolean(),"Offset must be numeric");out.offset_mv=j["offset_mv"].get<double>();require(std::isfinite(out.offset_mv),"Offset must be finite");
 const auto matches=[&](const ProfileJson& recipe){return digest(recipe)==out.recipe_sha256;};
 if(out.profile=="RTX 2080 Ti - NVVDD (MP2888A)"&&out.rail=="NVVDD"){
  auto recipe=ProfileJson::parse(released_mp2888);if(out.route.port!=1||out.route.addr7!=0x20){recipe["bus"]={{"port",out.route.port},{"addr7",out.route.addr7}};recipe["match"]=ProfileJson::object();recipe["identity"]=ProfileJson::array({{{"reg",0xbe},{"bytes",1},{"mask",0x7f},{"value",out.route.addr7},{"fingerprint",true}}});recipe["discovery"]={{"controller","MP2888A candidate"},{"fingerprint_version",1}};}
  require(matches(recipe),"Unsupported MP2888 recipe hash; custom source is unavailable");const auto raw=out.offset_mv/6.25;require(raw>=-111&&raw<=112&&std::trunc(raw)==raw,"MP2888 offset requires exact 6.25 mV steps");out.family=I2cFamily::mp2888;return out;
 }
 for(int page=0;page<2;++page)for(int scale=0;scale<8;++scale){const bool original=out.route.port==2&&out.route.addr7==0x30&&page==0&&scale==1;const auto label=original?std::string("ASUS RTX 5080 Astral - MP29816 (write path unverified)"):"MP29816 PAGE "+std::to_string(page)+" output";const auto rail=original?std::string("NVVDD"):"PAGE "+std::to_string(page)+" output";if(out.profile!=label||out.rail!=rail)continue;
  auto recipe=ProfileJson::parse(released_mp29816);if(!original){recipe["bus"]={{"port",out.route.port},{"addr7",out.route.addr7}};recipe["match"]=ProfileJson::object();recipe["identity"]=ProfileJson::array({{{"reg",0xad},{"bytes",5},{"equals",uint64_t(0x0002a81604ULL)}},{{"reg",0},{"bytes",1},{"equals",page}},{{"reg",0x29},{"bytes",2},{"mask",0x1c00},{"value",scale<<10}}});recipe["discovery"]={{"controller","MP29816"},{"version",1},{"page",page},{"vout_scale_selector",scale}};recipe["profile"]["rail"]=rail;const double scales[]={6.25,5.0,2.5,2.0,1.0,1.0/256,1.0/512,1.0/1024};for(auto& item:recipe["telemetry"])if(item.value("key",std::string{})=="vout_mv")item["scale"]=scales[scale];if(scale!=1)recipe.erase("write");}
  if(!matches(recipe))continue;const auto raw=out.offset_mv/5.0;require(raw>=-128&&raw<=127&&std::trunc(raw)==raw,"MP29816 offset requires exact 5 mV steps");out.family=I2cFamily::mp29816;out.page=page;out.scale=scale;return out;
 }
 throw std::runtime_error("Unsupported offset recipe or hash; custom source is unavailable");
}

